-- Adds the PostgreSQL syntax list of src/plugins/packs/commands.json (v0.71.0) to workspaces saved before it, as
-- 0009_seed_command_lists does for the other command lists and with the same rules: a list with its id or name is kept
-- as it is, and a workspace that would go over 100 lists or the size the app saves (MaxListsBytes) is left as it is.
WITH pack AS (
  SELECT list, position FROM jsonb_array_elements('[{"id":"postgresql-syntax","name":"PostgreSQL構文","words":[{"display":"SHOW server_version;","input":"SHOW server_version;","annotation":"対象バージョン：例の利用条件（PostgreSQL 15以降を想定した主要構文。各例は独立した断片で、表・列・権限等の準備が必要）"},{"display":"CREATE TABLE users (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, email text UNIQUE, age integer CHECK (age >= 0), active boolean NOT NULL DEFAULT true, department_id bigint, created_at timestamptz NOT NULL DEFAULT now(), profile jsonb NOT NULL DEFAULT ''{}''::jsonb, tags text[] NOT NULL DEFAULT ''{}''); CREATE TABLE orders (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id bigint REFERENCES users(id), amount numeric(12,2) NOT NULL, status text NOT NULL DEFAULT ''pending'', created_at timestamptz NOT NULL DEFAULT now());","input":"CREATE TABLE users (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, email text UNIQUE, age integer CHECK (age >= 0), active boolean NOT NULL DEFAULT true, department_id bigint, created_at timestamptz NOT NULL DEFAULT now(), profile jsonb NOT NULL DEFAULT ''{}''::jsonb, tags text[] NOT NULL DEFAULT ''{}''); CREATE TABLE orders (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id bigint REFERENCES users(id), amount numeric(12,2) NOT NULL, status text NOT NULL DEFAULT ''pending'', created_at timestamptz NOT NULL DEFAULT now());","annotation":"サンプルテーブル：例に使う表を作成（空の検証用スキーマ向け。同名表があると失敗。以下の例を全部順番に実行する用途ではない）"},{"display":"SELECT 1; SELECT 2;","input":"SELECT 1; SELECT 2;","annotation":";：文を区切る"},{"display":"/* 1行コメント */ SELECT /* ブロックコメント */ 1;","input":"/* 1行コメント */ SELECT /* ブロックコメント */ 1;","annotation":"-- / /* ... */：コメント"},{"display":"SELECT ''Pomo'';","input":"SELECT ''Pomo'';","annotation":"''文字列''：文字列リテラル（文字列中の単一引用符は''''で表す）"},{"display":"SELECT name AS \"表示名\" FROM users;","input":"SELECT name AS \"表示名\" FROM users;","annotation":"\"識別子\"：識別子の引用（引用しない識別子は小文字として扱う。文字列の引用とは異なる）"},{"display":"SELECT * FROM public.users;","input":"SELECT * FROM public.users;","annotation":"スキーマ.表：スキーマ修飾（同名オブジェクトの曖昧さを避ける）"},{"display":"PREPARE find_user(bigint) AS SELECT * FROM users WHERE id = $1; EXECUTE find_user(1); DEALLOCATE find_user;","input":"PREPARE find_user(bigint) AS SELECT * FROM users WHERE id = $1; EXECUTE find_user(1); DEALLOCATE find_user;","annotation":"$1等のパラメーター：値をパラメーター化（アプリではドライバーのパラメーターAPIを使用。識別子は値パラメーターでは置き換えられない）"},{"display":"SELECT id, name FROM users;","input":"SELECT id, name FROM users;","annotation":"SELECT / FROM：列を取得"},{"display":"SELECT * FROM users;","input":"SELECT * FROM users;","annotation":"SELECT *：全列を取得（列追加の影響を受けやすい）"},{"display":"SELECT name AS display_name FROM users AS u;","input":"SELECT name AS display_name FROM users AS u;","annotation":"AS：別名を付ける"},{"display":"SELECT * FROM users WHERE age >= 20;","input":"SELECT * FROM users WHERE age >= 20;","annotation":"WHERE：条件で絞る"},{"display":"SELECT * FROM users WHERE active AND (age >= 20 OR age IS NULL);","input":"SELECT * FROM users WHERE active AND (age >= 20 OR age IS NULL);","annotation":"AND / OR / NOT：条件を組み合わせる（混在時は括弧で意図を明示）"},{"display":"SELECT * FROM users WHERE age <> 20;","input":"SELECT * FROM users WHERE age <> 20;","annotation":"比較演算子：比較（NULLとの通常比較は真偽がunknownになる）"},{"display":"SELECT * FROM users WHERE id IN (1, 2, 3);","input":"SELECT * FROM users WHERE id IN (1, 2, 3);","annotation":"IN：候補に含まれるか"},{"display":"SELECT * FROM users WHERE id NOT IN (1, 2);","input":"SELECT * FROM users WHERE id NOT IN (1, 2);","annotation":"NOT IN：候補に含まれないか（候補にNULLを含むと意図しない結果になり得る。NOT EXISTSも検討）"},{"display":"SELECT * FROM users WHERE age BETWEEN 20 AND 29;","input":"SELECT * FROM users WHERE age BETWEEN 20 AND 29;","annotation":"BETWEEN：両端を含む範囲（日時では>=と<の半開区間が便利）"},{"display":"SELECT * FROM users WHERE email IS NULL;","input":"SELECT * FROM users WHERE email IS NULL;","annotation":"IS NULL / IS NOT NULL：NULLの判定"},{"display":"SELECT * FROM users WHERE age IS DISTINCT FROM 20;","input":"SELECT * FROM users WHERE age IS DISTINCT FROM 20;","annotation":"IS DISTINCT FROM：NULLを含めた不等比較（NULLも比較可能な値として扱う）"},{"display":"SELECT * FROM users WHERE name LIKE ''Po%'';","input":"SELECT * FROM users WHERE name LIKE ''Po%'';","annotation":"LIKE：パターン一致（%は任意長、_は任意1文字）"},{"display":"SELECT * FROM users WHERE name ILIKE ''po%'';","input":"SELECT * FROM users WHERE name ILIKE ''po%'';","annotation":"ILIKE：大文字小文字を区別しない一致（大文字小文字の扱いはロケール等に依存）"},{"display":"SELECT * FROM users WHERE name ~* ''^po'';","input":"SELECT * FROM users WHERE name ~* ''^po'';","annotation":"~ / ~*：正規表現一致（~*は大文字小文字を区別しない）"},{"display":"SELECT * FROM users ORDER BY created_at DESC, id DESC;","input":"SELECT * FROM users ORDER BY created_at DESC, id DESC;","annotation":"ORDER BY：並べ替え（指定しない取得順は保証されない）"},{"display":"SELECT * FROM users ORDER BY age ASC NULLS LAST;","input":"SELECT * FROM users ORDER BY age ASC NULLS LAST;","annotation":"NULLS FIRST / LAST：NULLの並び位置"},{"display":"SELECT * FROM users ORDER BY id LIMIT 20 OFFSET 40;","input":"SELECT * FROM users ORDER BY id LIMIT 20 OFFSET 40;","annotation":"LIMIT / OFFSET：取得件数・開始位置（一意に並ぶORDER BYを指定。大きなOFFSETは負荷になり得る）"},{"display":"SELECT * FROM users WHERE id > 100 ORDER BY id LIMIT 20;","input":"SELECT * FROM users WHERE id > 100 ORDER BY id LIMIT 20;","annotation":"キ―セットページング：前回の続きから取得（前回の最終id等を使用）"},{"display":"SELECT DISTINCT department_id FROM users;","input":"SELECT DISTINCT department_id FROM users;","annotation":"DISTINCT：重複行を除く（選択した列全体で重複判定）"},{"display":"SELECT DISTINCT ON (department_id) department_id, id, created_at FROM users ORDER BY department_id, created_at DESC, id DESC;","input":"SELECT DISTINCT ON (department_id) department_id, id, created_at FROM users ORDER BY department_id, created_at DESC, id DESC;","annotation":"DISTINCT ON：グループごとに先頭行（PostgreSQL固有。DISTINCT ON式をORDER BYの左端に合わせる）"},{"display":"SELECT COUNT(*) FROM users;","input":"SELECT COUNT(*) FROM users;","annotation":"COUNT(*)：行数"},{"display":"SELECT COUNT(email) FROM users;","input":"SELECT COUNT(email) FROM users;","annotation":"COUNT(列)：非NULLの件数（NULLを数えない）"},{"display":"SELECT COUNT(DISTINCT department_id) FROM users;","input":"SELECT COUNT(DISTINCT department_id) FROM users;","annotation":"COUNT(DISTINCT 列)：非NULLの異なる値の数"},{"display":"SELECT SUM(amount), AVG(amount) FROM orders;","input":"SELECT SUM(amount), AVG(amount) FROM orders;","annotation":"SUM / AVG：合計・平均（対象なしの場合は通常NULL）"},{"display":"SELECT MIN(age), MAX(age) FROM users;","input":"SELECT MIN(age), MAX(age) FROM users;","annotation":"MIN / MAX：最小・最大"},{"display":"SELECT department_id, COUNT(*) FROM users GROUP BY department_id;","input":"SELECT department_id, COUNT(*) FROM users GROUP BY department_id;","annotation":"GROUP BY：グループ単位に集計"},{"display":"SELECT department_id, COUNT(*) FROM users GROUP BY department_id HAVING COUNT(*) >= 5;","input":"SELECT department_id, COUNT(*) FROM users GROUP BY department_id HAVING COUNT(*) >= 5;","annotation":"HAVING：集計後に絞る（WHEREは集計前の行に作用）"},{"display":"SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE active) AS active_count FROM users;","input":"SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE active) AS active_count FROM users;","annotation":"FILTER：集計の対象を条件指定"},{"display":"SELECT STRING_AGG(name, '', '' ORDER BY id) FROM users;","input":"SELECT STRING_AGG(name, '', '' ORDER BY id) FROM users;","annotation":"STRING_AGG：文字列を連結（順番が必要なら集計内でORDER BY）"},{"display":"SELECT ARRAY_AGG(id ORDER BY id) FROM users;","input":"SELECT ARRAY_AGG(id ORDER BY id) FROM users;","annotation":"ARRAY_AGG：配列へ集約"},{"display":"SELECT JSONB_AGG(name ORDER BY id) FROM users;","input":"SELECT JSONB_AGG(name ORDER BY id) FROM users;","annotation":"JSONB_AGG：JSON配列へ集約"},{"display":"SELECT u.name, o.amount FROM users u INNER JOIN orders o ON o.user_id = u.id;","input":"SELECT u.name, o.amount FROM users u INNER JOIN orders o ON o.user_id = u.id;","annotation":"INNER JOIN：一致する行を結合"},{"display":"SELECT u.id, o.id AS order_id FROM users u LEFT JOIN orders o ON o.user_id = u.id;","input":"SELECT u.id, o.id AS order_id FROM users u LEFT JOIN orders o ON o.user_id = u.id;","annotation":"LEFT JOIN：左側を残して結合（右側へのWHERE条件で実質INNER JOINになる場合がある）"},{"display":"SELECT u.id, o.id AS order_id FROM users u FULL OUTER JOIN orders o ON o.user_id = u.id;","input":"SELECT u.id, o.id AS order_id FROM users u FULL OUTER JOIN orders o ON o.user_id = u.id;","annotation":"FULL OUTER JOIN：両側の未一致行も残す"},{"display":"SELECT u.id, s.status FROM users u CROSS JOIN (VALUES (''pending''), (''paid'')) AS s(status);","input":"SELECT u.id, s.status FROM users u CROSS JOIN (VALUES (''pending''), (''paid'')) AS s(status);","annotation":"CROSS JOIN：直積（行数が掛け算で増える）"},{"display":"SELECT u.id, x.total FROM users u JOIN (SELECT user_id AS id, SUM(amount) AS total FROM orders GROUP BY user_id) x USING (id);","input":"SELECT u.id, x.total FROM users u JOIN (SELECT user_id AS id, SUM(amount) AS total FROM orders GROUP BY user_id) x USING (id);","annotation":"USING：同名の結合列を指定"},{"display":"SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);","input":"SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);","annotation":"EXISTS：対応する行があるか"},{"display":"SELECT * FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);","input":"SELECT * FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.id);","annotation":"NOT EXISTS：対応する行がないか"},{"display":"SELECT * FROM orders WHERE amount > (SELECT AVG(amount) FROM orders);","input":"SELECT * FROM orders WHERE amount > (SELECT AVG(amount) FROM orders);","annotation":"スカラーサブクエリ：単一値を式に使う（複数行を返すとエラー）"},{"display":"WITH totals AS (SELECT user_id, SUM(amount) AS total FROM orders GROUP BY user_id) SELECT * FROM totals WHERE total >= 1000;","input":"WITH totals AS (SELECT user_id, SUM(amount) AS total FROM orders GROUP BY user_id) SELECT * FROM totals WHERE total >= 1000;","annotation":"WITH / CTE：クエリに名前を付ける（必ず実体化されるわけではない）"},{"display":"WITH RECURSIVE nums(n) AS (VALUES (1) UNION ALL SELECT n + 1 FROM nums WHERE n < 5) SELECT n FROM nums;","input":"WITH RECURSIVE nums(n) AS (VALUES (1) UNION ALL SELECT n + 1 FROM nums WHERE n < 5) SELECT n FROM nums;","annotation":"WITH RECURSIVE：再帰クエリ（終了条件が必要）"},{"display":"SELECT u.id, recent.id AS order_id FROM users u LEFT JOIN LATERAL (SELECT id FROM orders o WHERE o.user_id = u.id ORDER BY created_at DESC, id DESC LIMIT 1) recent ON true;","input":"SELECT u.id, recent.id AS order_id FROM users u LEFT JOIN LATERAL (SELECT id FROM orders o WHERE o.user_id = u.id ORDER BY created_at DESC, id DESC LIMIT 1) recent ON true;","annotation":"LATERAL：左側の行を参照する副問い合わせ（ユーザーごとの最新注文など）"},{"display":"SELECT id FROM users WHERE active UNION ALL SELECT id FROM users WHERE NOT active;","input":"SELECT id FROM users WHERE active UNION ALL SELECT id FROM users WHERE NOT active;","annotation":"UNION / UNION ALL：結果を連結（UNIONは重複排除、UNION ALLは保持）"},{"display":"SELECT id FROM users EXCEPT SELECT user_id FROM orders;","input":"SELECT id FROM users EXCEPT SELECT user_id FROM orders;","annotation":"INTERSECT / EXCEPT：共通部分・差集合（列数と型に互換性が必要）"},{"display":"SELECT id, user_id, amount, SUM(amount) OVER (PARTITION BY user_id) AS user_total FROM orders;","input":"SELECT id, user_id, amount, SUM(amount) OVER (PARTITION BY user_id) AS user_total FROM orders;","annotation":"OVER / PARTITION BY：行を残したまま集計（GROUP BYと異なり各行を残す）"},{"display":"SELECT id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at, id) AS n FROM orders;","input":"SELECT id, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY created_at, id) AS n FROM orders;","annotation":"ROW_NUMBER：グループ内の連番（同順位の順番も決めるなら一意な並べ替え）"},{"display":"SELECT id, RANK() OVER (ORDER BY amount DESC), DENSE_RANK() OVER (ORDER BY amount DESC) FROM orders;","input":"SELECT id, RANK() OVER (ORDER BY amount DESC), DENSE_RANK() OVER (ORDER BY amount DESC) FROM orders;","annotation":"RANK / DENSE_RANK：順位（RANKは同順位後に欠番、DENSE_RANKは欠番なし）"},{"display":"SELECT id, LAG(amount) OVER (PARTITION BY user_id ORDER BY created_at, id) FROM orders;","input":"SELECT id, LAG(amount) OVER (PARTITION BY user_id ORDER BY created_at, id) FROM orders;","annotation":"LAG / LEAD：前後の行の値"},{"display":"SELECT id, SUM(amount) OVER (ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM orders;","input":"SELECT id, SUM(amount) OVER (ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM orders;","annotation":"ROWS BETWEEN：累積の窓枠（既定の窓枠との差に注意）"},{"display":"INSERT INTO users (name, email, age) VALUES (''Pomo'', ''pomo@example.com'', 20);","input":"INSERT INTO users (name, email, age) VALUES (''Pomo'', ''pomo@example.com'', 20);","annotation":"INSERT INTO / VALUES：行を追加"},{"display":"INSERT INTO users (name) VALUES (''A''), (''B'');","input":"INSERT INTO users (name) VALUES (''A''), (''B'');","annotation":"複数行INSERT：複数行を追加"},{"display":"INSERT INTO users (name) SELECT ''User '' || n FROM generate_series(1, 3) AS g(n);","input":"INSERT INTO users (name) SELECT ''User '' || n FROM generate_series(1, 3) AS g(n);","annotation":"INSERT ... SELECT：検索結果を挿入"},{"display":"INSERT INTO counters DEFAULT VALUES RETURNING id;","input":"INSERT INTO counters DEFAULT VALUES RETURNING id;","annotation":"DEFAULT VALUES：既定値で追加（IDENTITYの例で作成するcounters表向け。全必須列に既定値がある表で使用）"},{"display":"INSERT INTO users (name) VALUES (''Pomo'') RETURNING id, name;","input":"INSERT INTO users (name) VALUES (''Pomo'') RETURNING id, name;","annotation":"RETURNING：変更した行を返す（UPDATE・DELETEでも使用可能）"},{"display":"INSERT INTO users (name, email) VALUES (''Pomo'', ''pomo@example.com'') ON CONFLICT (email) DO NOTHING;","input":"INSERT INTO users (name, email) VALUES (''Pomo'', ''pomo@example.com'') ON CONFLICT (email) DO NOTHING;","annotation":"ON CONFLICT DO NOTHING：一意競合時に追加しない（対象に適切な一意制約・インデックスが必要）"},{"display":"INSERT INTO users (name, email) VALUES (''New'', ''pomo@example.com'') ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name RETURNING id, name;","input":"INSERT INTO users (name, email) VALUES (''New'', ''pomo@example.com'') ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name RETURNING id, name;","annotation":"ON CONFLICT DO UPDATE：一意競合時に更新（EXCLUDEDは挿入予定の行）"},{"display":"UPDATE users SET age = age + 1 WHERE id = 1 RETURNING id, age;","input":"UPDATE users SET age = age + 1 WHERE id = 1 RETURNING id, age;","annotation":"UPDATE / SET / WHERE：行を更新（WHEREなしは全行更新）"},{"display":"UPDATE users u SET active = true FROM (SELECT DISTINCT user_id FROM orders WHERE status = ''paid'') o WHERE u.id = o.user_id;","input":"UPDATE users u SET active = true FROM (SELECT DISTINCT user_id FROM orders WHERE status = ''paid'') o WHERE u.id = o.user_id;","annotation":"UPDATE ... FROM：別の表や結果を使って更新（対象行が複数の結合行に一致しないようにする）"},{"display":"DELETE FROM users WHERE id = 1 RETURNING id;","input":"DELETE FROM users WHERE id = 1 RETURNING id;","annotation":"DELETE / WHERE：行を削除（WHEREなしは全行削除。外部キー制約で拒否される場合がある）"},{"display":"DELETE FROM orders o USING users u WHERE o.user_id = u.id AND NOT u.active;","input":"DELETE FROM orders o USING users u WHERE o.user_id = u.id AND NOT u.active;","annotation":"DELETE ... USING：結合条件で削除"},{"display":"MERGE INTO users u USING (VALUES (''pomo@example.com'', ''Pomo'')) AS s(email, name) ON u.email = s.email WHEN MATCHED THEN UPDATE SET name = s.name WHEN NOT MATCHED THEN INSERT (email, name) VALUES (s.email, s.name);","input":"MERGE INTO users u USING (VALUES (''pomo@example.com'', ''Pomo'')) AS s(email, name) ON u.email = s.email WHEN MATCHED THEN UPDATE SET name = s.name WHEN NOT MATCHED THEN INSERT (email, name) VALUES (s.email, s.name);","annotation":"MERGE：一致条件に応じて更新・追加（PostgreSQL 15以降。ON CONFLICTと同じ競合処理保証ではない）"},{"display":"TRUNCATE TABLE orders;","input":"TRUNCATE TABLE orders;","annotation":"TRUNCATE：表をまとめて空にする（強いロックを取る。DELETEトリガーは発火しない）"},{"display":"TRUNCATE TABLE orders RESTART IDENTITY;","input":"TRUNCATE TABLE orders RESTART IDENTITY;","annotation":"TRUNCATE ... RESTART IDENTITY：表を空にし採番も戻す（全データ削除。表に所有されるシーケンスが対象）"},{"display":"CREATE TABLE notes (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, body text NOT NULL);","input":"CREATE TABLE notes (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, body text NOT NULL);","annotation":"CREATE TABLE：表を作る"},{"display":"CREATE TABLE counters (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY);","input":"CREATE TABLE counters (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY);","annotation":"IDENTITY：自動採番列（値の連続性・欠番なしを保証しない）"},{"display":"CREATE TABLE items (id bigint PRIMARY KEY);","input":"CREATE TABLE items (id bigint PRIMARY KEY);","annotation":"PRIMARY KEY：主キー（一意かつNOT NULL）"},{"display":"ALTER TABLE users ADD CONSTRAINT users_name_unique UNIQUE (name);","input":"ALTER TABLE users ADD CONSTRAINT users_name_unique UNIQUE (name);","annotation":"UNIQUE：一意制約（既存の重複があると失敗。通常NULL同士は同値としない）"},{"display":"ALTER TABLE users ALTER COLUMN email SET NOT NULL;","input":"ALTER TABLE users ALTER COLUMN email SET NOT NULL;","annotation":"NOT NULL：NULL禁止（既存NULLがあると失敗）"},{"display":"ALTER TABLE users ALTER COLUMN active SET DEFAULT true;","input":"ALTER TABLE users ALTER COLUMN active SET DEFAULT true;","annotation":"DEFAULT：既定値（既存行の値は変更しない）"},{"display":"ALTER TABLE orders ADD CONSTRAINT orders_amount_positive CHECK (amount >= 0);","input":"ALTER TABLE orders ADD CONSTRAINT orders_amount_positive CHECK (amount >= 0);","annotation":"CHECK：行の条件制約（条件がNULLの場合も通る。必要ならNOT NULLも併用）"},{"display":"CREATE TABLE reviews (id bigint PRIMARY KEY, user_id bigint REFERENCES users(id));","input":"CREATE TABLE reviews (id bigint PRIMARY KEY, user_id bigint REFERENCES users(id));","annotation":"FOREIGN KEY：外部キー（参照側インデックスは自動作成されない）"},{"display":"CREATE TABLE sessions (id bigint PRIMARY KEY, user_id bigint REFERENCES users(id) ON DELETE CASCADE);","input":"CREATE TABLE sessions (id bigint PRIMARY KEY, user_id bigint REFERENCES users(id) ON DELETE CASCADE);","annotation":"ON DELETE CASCADE：親削除時に子も削除（意図せぬ連鎖削除に注意）"},{"display":"ALTER TABLE users ADD COLUMN nickname text;","input":"ALTER TABLE users ADD COLUMN nickname text;","annotation":"ALTER TABLE ADD COLUMN：列を追加"},{"display":"ALTER TABLE users DROP COLUMN nickname;","input":"ALTER TABLE users DROP COLUMN nickname;","annotation":"ALTER TABLE DROP COLUMN：列を削除（列データを失う）"},{"display":"ALTER TABLE users ALTER COLUMN age TYPE bigint USING age::bigint;","input":"ALTER TABLE users ALTER COLUMN age TYPE bigint USING age::bigint;","annotation":"ALTER COLUMN TYPE：列型を変更（ロック・書き換えの負荷が発生する場合がある）"},{"display":"ALTER TABLE users RENAME COLUMN nickname TO display_name;","input":"ALTER TABLE users RENAME COLUMN nickname TO display_name;","annotation":"RENAME COLUMN / TO：列名・表名を変更（この例はnickname列がある場合）"},{"display":"ALTER TABLE users DROP CONSTRAINT users_name_unique;","input":"ALTER TABLE users DROP CONSTRAINT users_name_unique;","annotation":"DROP CONSTRAINT：制約を削除（制約が存在する場合）"},{"display":"CREATE TABLE user_snapshot AS SELECT id, name FROM users;","input":"CREATE TABLE user_snapshot AS SELECT id, name FROM users;","annotation":"CREATE TABLE AS：検索結果で表を作る（元表の制約・インデックス等は通常引き継がない）"},{"display":"DROP TABLE notes;","input":"DROP TABLE notes;","annotation":"DROP TABLE：表を削除（表とデータを失う。CASCADEは依存オブジェクトにも影響）"},{"display":"CREATE SCHEMA app;","input":"CREATE SCHEMA app;","annotation":"CREATE SCHEMA：スキーマを作る"},{"display":"SELECT 42::integer, 10000000000::bigint;","input":"SELECT 42::integer, 10000000000::bigint;","annotation":"integer / bigint：整数"},{"display":"SELECT 123.45::numeric(12,2);","input":"SELECT 123.45::numeric(12,2);","annotation":"numeric(p,s)：正確な小数（金額等。精度・スケールに制約）"},{"display":"SELECT 0.1::double precision;","input":"SELECT 0.1::double precision;","annotation":"double precision：近似の浮動小数点（正確な10進小数ではない）"},{"display":"SELECT ''hello''::text, ''abc''::varchar(10);","input":"SELECT ''hello''::text, ''abc''::varchar(10);","annotation":"text / varchar(n)：文字列（varchar(n)は長さ制限）"},{"display":"SELECT true, false, NULL::boolean;","input":"SELECT true, false, NULL::boolean;","annotation":"boolean：真偽値"},{"display":"SELECT DATE ''2026-01-01'', TIMESTAMP ''2026-01-01 12:00:00'';","input":"SELECT DATE ''2026-01-01'', TIMESTAMP ''2026-01-01 12:00:00'';","annotation":"date / timestamp：日付・タイムゾーンなし日時（timestamp単独はwithout time zone）"},{"display":"SELECT TIMESTAMPTZ ''2026-01-01 12:00:00+09'';","input":"SELECT TIMESTAMPTZ ''2026-01-01 12:00:00+09'';","annotation":"timestamptz：時点を扱う日時（表示はセッションTimeZoneに依存。元の地域名は保持しない）"},{"display":"SELECT INTERVAL ''7 days'';","input":"SELECT INTERVAL ''7 days'';","annotation":"interval：期間"},{"display":"SELECT gen_random_uuid();","input":"SELECT gen_random_uuid();","annotation":"uuid：UUID（例の関数はPostgreSQL 15以降で組込み）"},{"display":"SELECT ''{\"name\":\"Pomo\"}''::jsonb;","input":"SELECT ''{\"name\":\"Pomo\"}''::jsonb;","annotation":"json / jsonb：JSON（jsonbはインデックス対応。キー順・重複キーの保持等がjsonと異なる）"},{"display":"SELECT ARRAY[''go'', ''sql'']::text[];","input":"SELECT ARRAY[''go'', ''sql'']::text[];","annotation":"型[] / ARRAY：配列（PostgreSQLの配列添字は通常1から）"},{"display":"SELECT decode(''4869'', ''hex'');","input":"SELECT decode(''4869'', ''hex'');","annotation":"bytea：バイナリ"},{"display":"SELECT name, CASE WHEN age >= 20 THEN ''成人'' ELSE ''その他'' END FROM users;","input":"SELECT name, CASE WHEN age >= 20 THEN ''成人'' ELSE ''その他'' END FROM users;","annotation":"CASE WHEN：条件に応じた値"},{"display":"SELECT COALESCE(email, ''未登録'') FROM users;","input":"SELECT COALESCE(email, ''未登録'') FROM users;","annotation":"COALESCE：最初の非NULL値"},{"display":"SELECT amount / NULLIF(0, 0) FROM orders;","input":"SELECT amount / NULLIF(0, 0) FROM orders;","annotation":"NULLIF：等しいならNULL（ゼロ除算回避等）"},{"display":"SELECT CAST(''123'' AS integer), ''123''::integer;","input":"SELECT CAST(''123'' AS integer), ''123''::integer;","annotation":"CAST / ::：型変換（変換不可はエラー）"},{"display":"SELECT name || ''さん'', CONCAT(name, ''さん'') FROM users;","input":"SELECT name || ''さん'', CONCAT(name, ''さん'') FROM users;","annotation":"|| / CONCAT：文字列連結（||はNULLがあると通常NULL。CONCATはNULL引数を無視）"},{"display":"SELECT LOWER(name), UPPER(name), TRIM(name) FROM users;","input":"SELECT LOWER(name), UPPER(name), TRIM(name) FROM users;","annotation":"LOWER / UPPER / TRIM：文字列加工"},{"display":"SELECT LENGTH(name), SUBSTRING(name FROM 1 FOR 2) FROM users;","input":"SELECT LENGTH(name), SUBSTRING(name FROM 1 FOR 2) FROM users;","annotation":"LENGTH / SUBSTRING：長さ・部分文字列（LENGTH(text)は文字数）"},{"display":"SELECT ROUND(123.456::numeric, 2);","input":"SELECT ROUND(123.456::numeric, 2);","annotation":"ROUND：小数を丸める（小数桁指定の例はnumeric）"},{"display":"SELECT CURRENT_DATE, NOW();","input":"SELECT CURRENT_DATE, NOW();","annotation":"CURRENT_DATE / NOW：現在の日付・日時（NOWはトランザクション開始時点）"},{"display":"SELECT clock_timestamp();","input":"SELECT clock_timestamp();","annotation":"clock_timestamp：実際の現在時刻（同一文の実行中にも変化し得る）"},{"display":"SELECT DATE_TRUNC(''month'', created_at), COUNT(*) FROM users GROUP BY DATE_TRUNC(''month'', created_at);","input":"SELECT DATE_TRUNC(''month'', created_at), COUNT(*) FROM users GROUP BY DATE_TRUNC(''month'', created_at);","annotation":"DATE_TRUNC：日時を指定単位へ切り捨て（timestamptzではTimeZoneに注意）"},{"display":"SELECT EXTRACT(YEAR FROM created_at) FROM users;","input":"SELECT EXTRACT(YEAR FROM created_at) FROM users;","annotation":"EXTRACT：日時の要素を取得"},{"display":"SELECT NOW() - INTERVAL ''7 days'';","input":"SELECT NOW() - INTERVAL ''7 days'';","annotation":"日時 + INTERVAL：日時の加減算"},{"display":"SELECT NOW() AT TIME ZONE ''Asia/Tokyo'';","input":"SELECT NOW() AT TIME ZONE ''Asia/Tokyo'';","annotation":"AT TIME ZONE：タイムゾーンの解釈・変換（入力型により戻り値型・意味が異なる）"},{"display":"SELECT * FROM generate_series(1, 5);","input":"SELECT * FROM generate_series(1, 5);","annotation":"generate_series：連番等を生成"},{"display":"SELECT profile->''address'', profile->>''name'' FROM users;","input":"SELECT profile->''address'', profile->>''name'' FROM users;","annotation":"-> / ->>：JSON要素の取得（->はJSON、->>はtext）"},{"display":"SELECT profile #>> ''{address,city}'' FROM users;","input":"SELECT profile #>> ''{address,city}'' FROM users;","annotation":"#> / #>>：JSONの深いパス"},{"display":"SELECT * FROM users WHERE profile @> ''{\"premium\":true}''::jsonb;","input":"SELECT * FROM users WHERE profile @> ''{\"premium\":true}''::jsonb;","annotation":"@>：JSONB包含"},{"display":"SELECT * FROM users WHERE profile ? ''name'';","input":"SELECT * FROM users WHERE profile ? ''name'';","annotation":"?：JSONBのキー等の存在（ドライバーによってプレースホルダー記号との扱いに注意）"},{"display":"UPDATE users SET profile = jsonb_set(profile, ''{premium}'', ''true''::jsonb) WHERE id = 1;","input":"UPDATE users SET profile = jsonb_set(profile, ''{premium}'', ''true''::jsonb) WHERE id = 1;","annotation":"jsonb_set：JSONBの一部を変更（深いパスの途中のキーがない場合等に注意）"},{"display":"SELECT jsonb_build_object(''id'', id, ''name'', name) FROM users;","input":"SELECT jsonb_build_object(''id'', id, ''name'', name) FROM users;","annotation":"jsonb_build_object：JSONBオブジェクトを構築"},{"display":"SELECT * FROM users WHERE ''sql'' = ANY(tags);","input":"SELECT * FROM users WHERE ''sql'' = ANY(tags);","annotation":"ANY：配列要素との比較"},{"display":"SELECT * FROM users WHERE tags && ARRAY[''go'', ''sql''];","input":"SELECT * FROM users WHERE tags && ARRAY[''go'', ''sql''];","annotation":"&&：配列の重なり"},{"display":"SELECT id, unnest(tags) AS tag FROM users;","input":"SELECT id, unnest(tags) AS tag FROM users;","annotation":"unnest：配列を行へ展開"},{"display":"CREATE INDEX users_created_at_idx ON users(created_at);","input":"CREATE INDEX users_created_at_idx ON users(created_at);","annotation":"CREATE INDEX：検索用インデックス（読み取りが速くなる場合があるが更新・容量コストが増える）"},{"display":"CREATE INDEX orders_user_created_idx ON orders(user_id, created_at DESC);","input":"CREATE INDEX orders_user_created_idx ON orders(user_id, created_at DESC);","annotation":"複合インデックス：複数列のインデックス（列順・条件・並べ替えに合わせて設計）"},{"display":"CREATE INDEX users_active_idx ON users(id) WHERE active;","input":"CREATE INDEX users_active_idx ON users(id) WHERE active;","annotation":"部分インデックス：条件に合う行だけを索引化（クエリ条件と述語の関係が重要）"},{"display":"CREATE INDEX users_lower_email_idx ON users(LOWER(email));","input":"CREATE INDEX users_lower_email_idx ON users(LOWER(email));","annotation":"式インデックス：式の結果を索引化"},{"display":"CREATE INDEX users_profile_gin_idx ON users USING GIN(profile);","input":"CREATE INDEX users_profile_gin_idx ON users USING GIN(profile);","annotation":"USING GIN：JSONB等向けGIN索引（演算子・演算子クラスにより対応が異なる）"},{"display":"CREATE INDEX CONCURRENTLY users_age_idx ON users(age);","input":"CREATE INDEX CONCURRENTLY users_age_idx ON users(age);","annotation":"CREATE INDEX CONCURRENTLY：書き込みを止めにくい索引作成（トランザクションブロック内不可。失敗時に無効索引が残り得る）"},{"display":"DROP INDEX users_age_idx;","input":"DROP INDEX users_age_idx;","annotation":"DROP INDEX：インデックス削除（その索引が存在する場合）"},{"display":"CREATE VIEW active_users AS SELECT id, name FROM users WHERE active;","input":"CREATE VIEW active_users AS SELECT id, name FROM users WHERE active;","annotation":"CREATE VIEW：クエリをビューとして保存（通常は結果を保存しない）"},{"display":"CREATE MATERIALIZED VIEW user_totals AS SELECT user_id, SUM(amount) AS total FROM orders GROUP BY user_id;","input":"CREATE MATERIALIZED VIEW user_totals AS SELECT user_id, SUM(amount) AS total FROM orders GROUP BY user_id;","annotation":"CREATE MATERIALIZED VIEW：結果を保存するビュー（元表変更だけでは内容が自動更新されない）"},{"display":"REFRESH MATERIALIZED VIEW user_totals;","input":"REFRESH MATERIALIZED VIEW user_totals;","annotation":"REFRESH MATERIALIZED VIEW：保存結果を更新（通常は参照をブロック。CONCURRENTLYには適切な一意索引等が必要）"},{"display":"BEGIN; UPDATE users SET active = false WHERE id = 1; COMMIT;","input":"BEGIN; UPDATE users SET active = false WHERE id = 1; COMMIT;","annotation":"BEGIN / COMMIT：処理をまとめて確定（実行すると変更が確定）"},{"display":"BEGIN; UPDATE users SET active = false WHERE id = 1; ROLLBACK;","input":"BEGIN; UPDATE users SET active = false WHERE id = 1; ROLLBACK;","annotation":"ROLLBACK：変更を取り消す（シーケンスの採番等は巻き戻らない）"},{"display":"BEGIN; SAVEPOINT before_change; UPDATE users SET active = false WHERE id = 1; ROLLBACK TO SAVEPOINT before_change; COMMIT;","input":"BEGIN; SAVEPOINT before_change; UPDATE users SET active = false WHERE id = 1; ROLLBACK TO SAVEPOINT before_change; COMMIT;","annotation":"SAVEPOINT：途中の復帰地点"},{"display":"BEGIN READ ONLY; SELECT * FROM users; COMMIT;","input":"BEGIN READ ONLY; SELECT * FROM users; COMMIT;","annotation":"READ ONLY：読み取り専用トランザクション"},{"display":"BEGIN ISOLATION LEVEL SERIALIZABLE; SELECT * FROM users WHERE id = 1; COMMIT;","input":"BEGIN ISOLATION LEVEL SERIALIZABLE; SELECT * FROM users WHERE id = 1; COMMIT;","annotation":"ISOLATION LEVEL：分離レベルを指定（直列化失敗時はトランザクション全体の再試行が必要）"},{"display":"BEGIN; SELECT * FROM users WHERE id = 1 FOR UPDATE; COMMIT;","input":"BEGIN; SELECT * FROM users WHERE id = 1 FOR UPDATE; COMMIT;","annotation":"FOR UPDATE：取得行を更新用にロック（ロックは通常トランザクション終了まで）"},{"display":"BEGIN; SELECT * FROM orders WHERE status = ''pending'' ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1; COMMIT;","input":"BEGIN; SELECT * FROM orders WHERE status = ''pending'' ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1; COMMIT;","annotation":"SKIP LOCKED：ロック済み行を飛ばす（ジョブキュー等向け。一般的な整合した一覧取得には不向き）"},{"display":"BEGIN; SET LOCAL lock_timeout = ''3s''; SELECT * FROM users WHERE id = 1 FOR UPDATE; COMMIT;","input":"BEGIN; SET LOCAL lock_timeout = ''3s''; SELECT * FROM users WHERE id = 1 FOR UPDATE; COMMIT;","annotation":"SET LOCAL lock_timeout：ロック待機を制限（SET LOCALは現在トランザクション内だけ）"},{"display":"EXPLAIN SELECT * FROM users WHERE id = 1;","input":"EXPLAIN SELECT * FROM users WHERE id = 1;","annotation":"EXPLAIN：実行計画を表示（通常は対象SQLを実行しない）"},{"display":"EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM users WHERE id = 1;","input":"EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM users WHERE id = 1;","annotation":"EXPLAIN ANALYZE：実行して実測計画を表示（対象SQLを実際に実行。UPDATE・DELETE等にも副作用がある）"},{"display":"ANALYZE users;","input":"ANALYZE users;","annotation":"ANALYZE：統計情報を更新（対象に適切な権限が必要）"},{"display":"VACUUM (ANALYZE) users;","input":"VACUUM (ANALYZE) users;","annotation":"VACUUM：不要領域の再利用等（トランザクションブロック内不可。通常OSへ容量を返す処理ではない）"},{"display":"CREATE ROLE app_reader;","input":"CREATE ROLE app_reader;","annotation":"CREATE ROLE：ロール作成（適切な管理権限が必要）"},{"display":"GRANT USAGE ON SCHEMA public TO app_reader; GRANT SELECT ON users TO app_reader;","input":"GRANT USAGE ON SCHEMA public TO app_reader; GRANT SELECT ON users TO app_reader;","annotation":"GRANT：権限付与（既存のusers表が対象。将来の表には別設定が必要）"},{"display":"REVOKE SELECT ON users FROM app_reader;","input":"REVOKE SELECT ON users FROM app_reader;","annotation":"REVOKE：権限を取り消す（他ロール経由等の権限は残る場合がある）"},{"display":"COPY (SELECT id, name FROM users) TO ''/tmp/users.csv'' WITH (FORMAT csv, HEADER true);","input":"COPY (SELECT id, name FROM users) TO ''/tmp/users.csv'' WITH (FORMAT csv, HEADER true);","annotation":"COPY：サーバー側CSV出力（サーバー上のパス。特別なファイル権限等が必要。クライアントのパスではない）"},{"display":"SHOW TimeZone;","input":"SHOW TimeZone;","annotation":"SHOW：設定を確認"},{"display":"SELECT column_name, data_type FROM information_schema.columns WHERE table_schema = ''public'' AND table_name = ''users'' ORDER BY ordinal_position;","input":"SELECT column_name, data_type FROM information_schema.columns WHERE table_schema = ''public'' AND table_name = ''users'' ORDER BY ordinal_position;","annotation":"information_schema：表の構造等を参照（権限で見える範囲が変わる）"}],"records":[],"createdAt":"2026-10-23T00:00:00.000Z"}]'::jsonb) WITH ORDINALITY AS t(list, position)
), missing AS (
  SELECT w.owner_id, jsonb_agg(pack.list ORDER BY pack.position) AS lists
  FROM "typle_workspaces" w CROSS JOIN pack
  WHERE jsonb_typeof(w.lists) = 'array' AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(w.lists) saved
    WHERE saved->>'id' = pack.list->>'id' OR lower(btrim(saved->>'name')) = lower(pack.list->>'name'))
  GROUP BY w.owner_id
)
UPDATE "typle_workspaces" w
SET lists = w.lists || missing.lists, revision = w.revision + 1, updated_at = now()
FROM missing
WHERE w.owner_id = missing.owner_id
  AND jsonb_array_length(w.lists) + jsonb_array_length(missing.lists) <= 100
  AND octet_length(w.lists::text) + octet_length(missing.lists::text) <= 896 * 1024;
